'use client'

import { useState } from 'react'
import type { Tournament } from '@/lib/types'

interface Props {
  tournament: Tournament | null
}

export function JsonPreview({ tournament }: Props) {
  const [copied, setCopied] = useState(false)

  if (!tournament) {
    return (
      <div className="bg-white rounded-lg border border-gray-200 shadow-sm p-6">
        <div className="text-center text-gray-400 text-sm">
          <p className="mb-2">填写左侧表单后，JSON 预览将显示在这里</p>
          <p className="text-xs">生成的 JSON 可以直接提交到 GitHub 仓库</p>
        </div>
      </div>
    )
  }

  const json = JSON.stringify(tournament, null, 2)
  const filename = `${tournament.id}.json`

  const handleCopy = async () => {
    await navigator.clipboard.writeText(json)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const handleDownload = () => {
    const blob = new Blob([json], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = filename
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="bg-white rounded-lg border border-gray-200 shadow-sm flex flex-col max-h-[calc(100vh-180px)]">
      <div className="border-b border-gray-200 px-4 py-3 flex items-center justify-between shrink-0">
        <div>
          <h3 className="text-sm font-medium text-gray-900">JSON 预览</h3>
          <p className="text-xs text-gray-400 mt-0.5">{filename}</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={handleCopy}
            className="px-3 py-1.5 text-xs bg-gray-100 text-gray-700 rounded hover:bg-gray-200"
          >
            {copied ? '已复制' : '复制'}
          </button>
          <button
            onClick={handleDownload}
            className="px-3 py-1.5 text-xs bg-purple-600 text-white rounded hover:bg-purple-700"
          >
            下载 JSON
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto p-4">
        <pre className="text-xs font-mono text-gray-700 whitespace-pre-wrap break-all">
          {json}
        </pre>
      </div>

      <div className="border-t border-gray-200 px-4 py-3 shrink-0">
        <p className="text-xs text-gray-500">
          将此文件保存到 <code className="bg-gray-100 px-1 rounded">data/tournaments/{filename}</code> 并提交 PR
        </p>
      </div>
    </div>
  )
}
