'use client'

import type { BeatmapMeta } from '@/lib/types'

const RC_REAL_TYPES = [
  { id: 'SS', name: 'Speed Stream' },
  { id: 'JS', name: 'Jumpstream' },
  { id: 'CJ', name: 'Chordjack' },
  { id: 'SA', name: 'Stamina' },
  { id: 'HS', name: 'Handstream' },
  { id: 'TP', name: 'Tech/Pattern' },
]

const LN_REAL_TYPES = [
  { id: 'CO', name: 'Coordination' },
  { id: 'RE', name: 'Release' },
  { id: 'DE', name: 'Density' },
  { id: 'IN', name: 'Inverse' },
]

const HB_REAL_TYPES = [
  { id: 'HB1', name: 'Hybrid 1' },
  { id: 'HB2', name: 'Hybrid 2' },
  { id: 'HB3', name: 'Hybrid 3' },
]

const SV_REAL_TYPES = [
  { id: 'SV1', name: 'SV 1' },
  { id: 'SV2', name: 'SV 2' },
]

const TB_REAL_TYPES = [
  { id: 'TB', name: 'Tiebreaker' },
]

function getRealTypeOptions(type: string) {
  switch (type) {
    case 'RC': return RC_REAL_TYPES
    case 'LN': return LN_REAL_TYPES
    case 'HB': return HB_REAL_TYPES
    case 'SV': return SV_REAL_TYPES
    case 'TB': return TB_REAL_TYPES
    default: return [{ id: type, name: type }]
  }
}

const TYPE_COLORS: Record<string, string> = {
  RC: '#3b82f6',
  HB: '#8b5cf6',
  LN: '#6366f1',
  SV: '#f59e0b',
  TB: '#ef4444',
}

interface Props {
  map: BeatmapMeta
  onChange: (map: BeatmapMeta) => void
  onRemove: () => void
}

export function MapSlotEditor({ map, onChange, onRemove }: Props) {
  const isHB = map.type === 'HB'
  const isLN = map.type === 'LN'
  const isRC = map.type === 'RC' || map.type === 'SV' || map.type === 'TB'

  const updateField = <K extends keyof BeatmapMeta>(key: K, value: BeatmapMeta[K]) => {
    onChange({ ...map, [key]: value })
  }

  const difficultyHint = isRC
    ? 'RF 段位难度'
    : isLN
    ? 'LN 段位难度'
    : isHB
    ? 'RF 段位难度'
    : '难度'

  const lnHint = 'LN 段位难度'

  return (
    <div className="flex items-center gap-2 p-2 bg-gray-50 rounded border border-gray-100">
      <div
        className="w-1.5 h-8 rounded-full shrink-0"
        style={{ background: TYPE_COLORS[map.type] || '#9ca3af' }}
      />

      <div className="flex items-center gap-1.5 flex-1 min-w-0">
        <span className="text-xs font-mono font-medium text-gray-700 w-8 shrink-0">
          {map.slot}
        </span>

        <select
          value={map.realType}
          onChange={(e) => updateField('realType', e.target.value)}
          className="px-1.5 py-1 border border-gray-200 rounded text-xs w-20 shrink-0 focus:outline-none focus:border-purple-400"
        >
          {getRealTypeOptions(map.type).map((rt) => (
            <option key={rt.id} value={rt.id}>{rt.name}</option>
          ))}
        </select>

        <div className="flex items-center gap-1">
          <input
            type="number"
            step="0.5"
            min="0"
            max="20"
            value={map.difficulty || ''}
            onChange={(e) => updateField('difficulty', Number(e.target.value))}
            placeholder={difficultyHint}
            className="w-16 px-1.5 py-1 border border-gray-200 rounded text-xs text-center focus:outline-none focus:border-purple-400"
            title={difficultyHint}
          />
          <span className="text-xs text-gray-400 shrink-0">
            {isRC ? 'rf' : isLN ? 'ln' : 'rf'}
          </span>
        </div>

        {isHB && (
          <div className="flex items-center gap-1">
            <input
              type="number"
              step="0.5"
              min="0"
              max="20"
              value={map.difficultyLn || ''}
              onChange={(e) => updateField('difficultyLn', Number(e.target.value) || undefined)}
              placeholder={lnHint}
              className="w-16 px-1.5 py-1 border border-gray-200 rounded text-xs text-center focus:outline-none focus:border-purple-400"
              title={lnHint}
            />
            <span className="text-xs text-gray-400 shrink-0">ln</span>
          </div>
        )}
      </div>

      <button
        onClick={onRemove}
        className="text-gray-300 hover:text-red-500 shrink-0"
        title="删除"
      >
        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>
    </div>
  )
}
